<?php $base='/research/'.$r['slug']; ?>
<div class="page-heading reader-heading"><h1>Read findings</h1><p class="reader-study-title"><?=e($r['title'])?></p><div class="actions primary-actions reader-actions"><a class="button" href="#authored-findings">Read authored findings</a><a class="button secondary" href="<?=e($base)?>/resources">Resources &amp; sources</a><a class="button secondary" href="<?=e($base)?>">Research brief</a></div></div>
<div class="reader-content"><p class="notice"><strong>Provisional findings.</strong> Publication is not proof. Read each contributor’s sources and limitations before relying on a finding.</p>
<p><strong><?=e($readerState['label'])?></strong> · <?=e($readerState['guidance'])?> <?=e($readerState['unblocker'])?> <a href="<?=e($readerState['href'])?>">Current next steps</a></p>
<section id="authored-findings" aria-labelledby="findings-title"><h2 id="findings-title">What authors report</h2><p class="fine"><?=count($findings)?> current public research result<?=count($findings)===1?'':'s'?> or supplementary contribution<?=count($findings)===1?'':'s'?>. Held, rejected and superseded packets do not supply this view. <a href="<?=e($base)?>/ledger">Review history</a></p>
<?php if(!$findings): ?><p>No current accepted research findings are available yet. Read the research brief or next steps; no conclusion has been inferred from planning, progress or held work.</p><?php endif ?>
<?php foreach($findings as $index=>$finding): $resultLink=$base.($finding['contribution']?'#contribution-':'/results/').$finding['id']; ?><details class="reader-finding" <?=($index===0?'open':'')?> id="reader-finding-<?=e($finding['id'])?>"><summary><?=e(ucfirst($finding['kind']))?> · <?=e($finding['title'])?></summary><div class="reader-finding-body"><p class="fine">By <?=e($finding['author'])?> · <?=e($finding['created_at'])?> UTC · Authorship and identity are declarations. <a href="<?=e($resultLink)?>">Full authored result &amp; evidence</a></p>
<?php if(!$finding['aid']): ?><p class="notice">No plain-language summary is available for this result. <a href="<?=e($resultLink)?>">Read the full authored result &amp; evidence</a> for the original detail.</p><?php endif ?>
<h3><?=e($finding['aid']?'Authored finding':'Author’s original conclusion or title')?></h3><?=prose($finding['finding'])?>
<h3>What this establishes</h3><?php if($finding['established']!==null): ?><?=prose($finding['established'])?><?php else: ?><p>Not supplied by the contributor. See the full result and sources.</p><?php endif ?>
<h3>What remains uncertain</h3><?=prose($finding['uncertain']?:'No separate uncertainty note was supplied.')?>
<h3>How this may be used</h3><?=prose($finding['next_use']?:'No authored scientific-use note was supplied.')?>
<?php if($finding['aid']): ?><details><summary>Why it matters, useful work and intended reader</summary><?php foreach(['why_it_matters'=>'Why it matters','increment'=>'Useful work added','reusable_output'=>'Reusable output','question_helped'=>'Question helped','intended_user'=>'Intended reader'] as $key=>$label): ?><h4><?=e($label)?></h4><?=prose($finding['aid'][$key])?><?php endforeach ?></details><?php endif ?>
<?php if($finding['workflow_next_actions']!==''): ?><details class="reader-workflow"><summary>Contributor workflow next steps</summary><p class="fine">Original contributor follow-up and workflow instructions.</p><?=prose($finding['workflow_next_actions'])?></details><?php endif ?>
<div class="actions"><a class="button secondary" href="<?=e($resultLink)?>">Full authored result &amp; evidence</a><a class="button secondary" href="<?=e($base)?>/resources">Source index</a></div></div></details><?php endforeach ?></section></div>
